import java.nio.file.*;import java.io.*;import java.security.*;import java.security.cert.*;
class BuildTrust { public static void main(String[] args)throws Exception {KeyStore store=KeyStore.getInstance("JKS");try(InputStream in=Files.newInputStream(Path.of(args[0]))){store.load(in,"changeit".toCharArray());}CertificateFactory factory=CertificateFactory.getInstance("X.509");int count=0;try(InputStream in=Files.newInputStream(Path.of(args[1]))){for(java.security.cert.Certificate certificate:factory.generateCertificates(in)){store.setCertificateEntry("windows-root-"+count++,certificate);}}try(OutputStream out=Files.newOutputStream(Path.of(args[2]))){store.store(out,"changeit".toCharArray());}System.out.println("Build trust store prepared with "+count+" Windows trusted root certificates; machine trust settings unchanged.");}}
